86	        return this.telephone;
87	    }
88	
89	    public void setTelephone(String telephone) {
90	        this.telephone = telephone;
91	    }
92	
93	    public String getEmail() {
94	        return this.email;
95	    }
96	
97	    public void setEmail(String email) {
98	        this.email = email;
99	    }
100	
101	    public LocalDate getRegistrationDate() {
102	        return this.registrationDate;
103	    }
104	
105	    public void setRegistrationDate(LocalDate registrationDate) {
106	        this.registrationDate = registrationDate;
107	    }
108	
109	    public String getCustomerCode() {
110	        return this.customerCode;
111	    }
112	
113	    public void setCustomerCode(String customerCode) {
114	        this.customerCode = customerCode;
115	    }
116	
117	    public String getHouseholdId() {
118	        return this.householdId;
119	    }
120	
121	    public void setHouseholdId(String householdId) {
122	        this.householdId = householdId;
123	    }
124	
125	    public Integer getNamesakeCount() {
126	        return this.namesakeCount;
127	    }
128	
129	    public void setNamesakeCount(Integer namesakeCount) {
130	        this.namesakeCount = namesakeCount;
131	    }
132	
133	    /**
134	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY
135	     * is the last two digits of the registration date's year (e.g. {@code "SMI-0007-M26"}).
136	     * Derived from the owner's own fields, so it stays consistent with them.
137	     */
138	    @Transient
139	    public String getMembershipNumber() {
140	        if (this.customerCode == null || this.registrationDate == null) {
141	            return null;
142	        }
143	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
144	    }
145	
146	    /**
147	     * The owner's membership tier: {@code "SILVER"} for a unique owner (namesake
148	     * count of zero) who has an email on file, and {@code "BRONZE"} otherwise.
149	     * Derived from the owner's own fields, so it stays consistent with them.
150	     */
151	    @Transient
152	    public String getMembershipTier() {
153	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
154	        boolean hasEmail = this.email != null && !this.email.isEmpty();
155	        return unique && hasEmail ? "SILVER" : "BRONZE";
156	    }
157	
158	    /**
159	     * Default the registration date to the server's current date when none was
160	     * supplied, so every newly persisted owner has a registration date.
161	     */
162	    @PrePersist
163	    void defaultRegistrationDate() {
164	        if (this.registrationDate == null) {
165	            this.registrationDate = LocalDate.now();
166	        }
167	    }
168	
169	    protected Set<Pet> getPetsInternal() {
170	        if (this.pets == null) {
171	            this.pets = new HashSet<>();
172	        }
173	        return this.pets;
174	    }
175	
176	    protected void setPetsInternal(Set<Pet> pets) {
177	        this.pets = pets;
178	    }
179	
180	    public List<Pet> getPets() {
181	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
182	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
183	        return Collections.unmodifiableList(sortedPets);
184	    }
185	
186	    public void setPets(List<Pet> pets) {
187	        this.pets = new HashSet<>(pets);
188	    }
189	
190	    public void addPet(Pet pet) {
191	        getPetsInternal().add(pet);
192	        pet.setOwner(this);
193	    }
194	
195	    /**
196	     * Return the Pet with the given name, or null if none found for this Owner.
197	     *
198	     * @param name to test
199	     * @return true if pet name is already in use
200	     */
201	    public Pet getPet(String name) {
202	        return getPet(name, false);
203	    }
204	
205	    /**
206	     * Return the Pet with the given name, or null if none found for this Owner.
207	     *
208	     * @param name to test
209	     * @return true if pet name is already in use
210	     */
211	    public Pet getPet(String name, boolean ignoreNew) {
212	        name = name.toLowerCase();
213	        for (Pet pet : getPetsInternal()) {
214	            if (!ignoreNew || !pet.isNew()) {
215	                String compName = pet.getName();
216	                compName = compName.toLowerCase();
217	                if (compName.equals(name)) {
218	                    return pet;
219	                }
220	            }
221	        }
222	        return null;
223	    }
224	
225	    public Pet getPet(Integer petId) {
226	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
227	    }
228	
229	    @Override
230	    public String toString() {
231	        return new ToStringCreator(this)
232	
233	            .append("id", this.getId())
234	            .append("new", this.isNew())
235	            .append("lastName", this.getLastName())
236	            .append("firstName", this.getFirstName())
237	            .append("address", this.address)
238	            .append("city", this.city)
239	            .append("telephone", this.telephone)
240	            .toString();
241	    }
242	}
