282	    public String shareHousehold(Owner owner) throws DataAccessException {
283	        String householdId = householdIdGenerator.generate(owner.getLastName(), owner.getAddress());
284	        // Backfill the existing members so the whole household carries one shared id.
285	        householdMembers(owner.getLastName(), owner.getAddress()).stream()
286	            .filter(member -> !householdId.equals(member.getHouseholdId()))
287	            .forEach(member -> {
288	                member.setHouseholdId(householdId);
289	                ownerRepository.save(member);
290	            });
291	        owner.setHouseholdId(householdId);
292	        return householdId;
293	    }
